import csv, os
OUT = '/home/user/learning_tokens/kb/structs/ondo'
os.makedirs(OUT, exist_ok=True)


def w(name, head, rows):
    with open(os.path.join(OUT, name), 'w', encoding='utf-8', newline='') as f:
        c = csv.writer(f)
        c.writerow(head)
        c.writerows(rows)
    print(name, len(rows))


